TargetContent:
"                            {REPORTS_LIST.map(item => {
                               const IconComponent = item.icon;
                               const isSelected = selectedReport === item.name;
                               return (
                                  <button
                                     key={item.name}
                                     onClick={() => setSelectedReport(item.name)}
                                     className={`w-full flex items-center gap-3 px-4 py-3.5 text-xs font-bold uppercase rounded-xl transition-all ${
                                        isSelected 
                                           ? 'bg-[#1e4630]/10 text-[#1e4630] border-l-4 border-[#1e4630] pl-3' 
                                           : 'text-slate-700 hover:bg-slate-50 border-l-4 border-transparent'
                                     }`}
                                  >
                                     <IconComponent size={16} className={isSelected ? 'text-[#1e4630]' : 'text-slate-400'} />
                                     <span className="truncate">{item.name}</span>
                                  </button>
                               );
                            })}"
